arguments.file_text:
namespace sv_ec69aadbad4f491a854fc4f0f3daf1cd.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@rendermode InteractiveServer
@using sv_ec69aadbad4f491a854fc4f0f3daf1cd.Services
@inject IChatService ChatService
@inject IJSRuntime JS

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar ── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (channels is not null)
            {
                @foreach (var channel in channels)
                {
                    <li class="channel-item @(channel.Id == activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@Truncate(channel.Description, 40)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <section class="message-area @(threadOpen ? "" : "expanded")">
        @if (activeChannel is not null)
        {
            <div class="message-header">
                <h2># @activeChannel.Name</h2>
                <p>@activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="messageListRef" @onscroll="OnMessageListScroll">
                @if (loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (messages is not null)
                {
                    @foreach (var msg in messages)
                    {
                        <div class="message-row" @onmouseenter="() => hoveredMessageId = msg.Id"
                             @onmouseleave="() => { if (hoveredMessageId == msg.Id) hoveredMessageId = null; }">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <span class="author">@msg.Author</span>
                                    <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in msg.Reactions)
                                        {
                                            <span class="reaction-badge" title="@string.Join(", ", r.Users)">
                                                @r.Emoji @r.Users.Count
                                            </span>
                                        }
                                    </div>
                                }

                                @{ var thread = threadSummaries.GetValueOrDefault(msg.Id); }
                                @if (thread is not null)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                        @thread.ReplyCount @(thread.ReplyCount == 1 ? "reply" : "replies")
                                        &middot; Last @FormatRelativeTime(thread.LastReplyAt)
                                    </button>
                                }
                            </div>

                            @if (hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">💬 Reply</button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" title="Add reaction"
                                                @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                        @if (emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in commonEmojis)
                                                {
                                                    <button class="emoji-option"
                                                            @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="compose-area">
                <textarea @bind="newMessageText" @bind:event="oninput"
                          placeholder="Type a message…"
                          @onkeydown="OnComposeKeyDown" rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ── Right Thread Panel ── *@
    @if (threadOpen)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            @if (threadRootMessage is not null)
            {
                <div class="thread-root-quote">
                    <div class="message-meta">
                        <span class="author">@threadRootMessage.Author</span>
                        <span class="timestamp">@FormatRelativeTime(threadRootMessage.SentAt)</span>
                    </div>
                    <div class="message-content">@threadRootMessage.Content</div>
                </div>
            }

            <div class="thread-replies">
                @if (threadMessages is not null)
                {
                    @foreach (var reply in threadMessages)
                    {
                        <div class="message-bubble">
                            <div class="message-meta">
                                <span class="author">@reply.Author</span>
                                <span class="timestamp">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>
                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in reply.Reactions)
                                    {
                                        <span class="reaction-badge" title="@string.Join(", ", r.Users)">
                                            @r.Emoji @r.Users.Count
                                        </span>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="compose-area">
                <textarea @bind="threadReplyText" @bind:event="oninput"
                          placeholder="Reply in thread…"
                          @onkeydown="OnThreadReplyKeyDown" rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "🚀"];

    // ── State ──
    private List<Channel>? channels;
    private int? activeChannelId;
    private Channel? activeChannel;
    private List<Message>? messages;
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private string newMessageText = "";
    private int messageSkip;
    private bool loadingOlder;
    private bool allOlderLoaded;

    // Hover / emoji picker
    private int? hoveredMessageId;
    private int? emojiPickerMessageId;

    // Thread panel
    private bool threadOpen;
    private int? activeThreadRootId;
    private Message? threadRootMessage;
    private List<Message>? threadMessages;
    private string threadReplyText = "";

    private ElementReference messageListRef;

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    // ── Channel selection ──
    private async Task SelectChannelAsync(Channel channel)
    {
        activeChannelId = channel.Id;
        activeChannel = channel;
        messageSkip = 0;
        allOlderLoaded = false;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;
        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channel.Id);
        RefreshChannelUnread(channel.Id);
    }

    private void RefreshChannelUnread(int channelId)
    {
        if (channels is null) return;
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var c = channels[idx];
            channels[idx] = c with { UnreadCount = 0 };
        }
    }

    // ── Pagination (scroll-to-top) ──
    private async Task OnMessageListScroll()
    {
        if (loadingOlder || allOlderLoaded || activeChannelId is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId.Value, messageSkip, PageSize);
        if (older.Count == 0)
        {
            allOlderLoaded = true;
        }
        else
        {
            messages = older.Concat(messages!).ToList();
            messageSkip += older.Count;
            BuildThreadSummaries();
        }
        loadingOlder = false;
    }

    // ── Send message ──
    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(newMessageText) || activeChannelId is null) return;
        var sent = await ChatService.SendMessageAsync(activeChannelId.Value, newMessageText.Trim(), null);
        messages ??= new();
        messages.Add(sent);
        messageSkip++;
        newMessageText = "";
    }

    private async Task OnComposeKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Reactions ──
    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        emojiPickerMessageId = null;

        // Optimistically update the message in the local list
        if (messages is not null)
        {
            var idx = messages.FindIndex(m => m.Id == messageId);
            if (idx >= 0)
            {
                var msg = messages[idx];
                var reactions = msg.Reactions.ToList();
                var existing = reactions.FindIndex(r => r.Emoji == emoji);
                if (existing >= 0)
                {
                    var r = reactions[existing];
                    if (!r.Users.Contains("You"))
                        reactions[existing] = r with { Users = r.Users.Concat(["You"]).ToList() };
                }
                else
                {
                    reactions.Add(new Reaction(emoji, ["You"]));
                }
                messages[idx] = msg with { Reactions = reactions };
            }
        }
    }

    // ── Thread panel ──
    private async Task OpenThreadAsync(int rootMessageId)
    {
        activeThreadRootId = rootMessageId;
        threadRootMessage = messages?.FirstOrDefault(m => m.Id == rootMessageId);
        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        activeThreadRootId = null;
        threadRootMessage = null;
        threadMessages = null;
        threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(threadReplyText) || activeThreadRootId is null || activeChannelId is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId.Value, threadReplyText.Trim(), activeThreadRootId);
        threadMessages ??= new();
        threadMessages.Add(reply);
        threadReplyText = "";
        UpdateThreadSummary(activeThreadRootId.Value);
    }

    private async Task OnThreadReplyKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Thread summaries ──
    private void BuildThreadSummaries()
    {
        threadSummaries.Clear();
        if (messages is null) return;

        // Messages with ReplyToId point to a root; group them.
        var replies = messages.Where(m => m.ReplyToId.HasValue).GroupBy(m => m.ReplyToId!.Value);
        foreach (var g in replies)
        {
            threadSummaries[g.Key] = new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt));
        }
    }

    private void UpdateThreadSummary(int rootId)
    {
        if (threadMessages is null) return;
        threadSummaries[rootId] = new ThreadSummary(rootId, threadMessages.Count, threadMessages.Max(m => m.SentAt));
    }

    // ── Helpers ──
    private static string Truncate(string text, int maxLen)
        => text.Length <= maxLen ? text : string.Concat(text.AsSpan(0, maxLen), "…");

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }
}

